// 编写日期：2026年8月5日
// 作者：zidong
// 程序说明：图书管理系统 - 自动化测试用例
// 用法：编译并运行 test_library，各用例通过则输出 [PASS]，失败输出 [FAIL]

#include <iostream>
#include <string>
#include <vector>
#include <cassert>
#include "book.hpp"
#include "user.hpp"
#include "admin.hpp"

using std::cout;
using std::endl;
using std::string;
using std::vector;

static int passCount = 0;
static int failCount = 0;

#define CHECK(cond, name)                                          \
    do {                                                           \
        if (cond) { ++passCount; cout << "[PASS] " << name << endl; } \
        else       { ++failCount; cout << "[FAIL] " << name << endl; } \
    } while (0)

// ---------- 用例一：Book 图书类基本功能 ----------
void testBook() {
    cout << "\n===== 用例一：Book 图书类 =====" << endl;

    Book b("B001", "C++入门", 3);
    CHECK(b.getId() == "B001", "图书编号 = B001");
    CHECK(b.getName() == "C++入门", "书名 = C++入门");
    CHECK(b.getStock() == 3, "初始库存 = 3");

    b.inStock(2);                          // 入库 2 本
    CHECK(b.getStock() == 5, "入库 2 本后库存 = 5");

    CHECK(b.borrowOne() == true, "借阅 1 本成功");
    CHECK(b.getStock() == 4, "借阅后库存 = 4");

    bool ok = b.outStock(10);              // 出库 10 本（库存不足）
    CHECK(ok == false, "出库 10 本（超过库存）应失败");
    CHECK(b.getStock() == 4, "出库失败后库存不变 = 4");

    b.returnOne();                         // 归还 1 本
    CHECK(b.getStock() == 5, "归还后库存 = 5");

    bool ok2 = b.outStock(-1);             // 负数出库
    CHECK(ok2 == false, "负数出库应失败");
}

// ---------- 用例二：User 用户类借阅/归还 ----------
void testUser() {
    cout << "\n===== 用例二：User 用户类 =====" << endl;

    User u("张三", "123456");
    CHECK(u.getUsername() == "张三", "用户名 = 张三");
    CHECK(u.getPassword() == "123456", "密码 = 123456");
    CHECK(u.borrowedCount() == 0u, "初始借阅数 = 0");

    CHECK(u.borrowBook("B001") == true, "借阅 B001 成功");
    CHECK(u.borrowBook("B001") == false, "重复借阅 B001 应失败");
    CHECK(u.borrowBook("B002") == true, "借阅 B002 成功");
    CHECK(u.borrowedCount() == 2u, "借阅数 = 2");
    CHECK(u.hasBorrowed("B001") == true, "已借阅 B001 = true");
    CHECK(u.hasBorrowed("B999") == false, "未借阅 B999 = false");

    CHECK(u.returnBook("B001") == true, "归还 B001 成功");
    CHECK(u.returnBook("B001") == false, "再次归还 B001 应失败");
    CHECK(u.returnBook("B999") == false, "归还未借过的 B999 应失败");
    CHECK(u.borrowedCount() == 1u, "归还后借阅数 = 1");

    const vector<string>& ids = u.getBorrowedIds();
    CHECK(ids.size() == 1u && ids[0] == "B002", "剩余借阅书目 = [B002]");
}

// ---------- 用例三：Admin 管理员出入库 ----------
void testAdmin() {
    cout << "\n===== 用例三：Admin 管理员出入库 =====" << endl;

    vector<Book> books;

    Admin::addBook(books, "B001", "C++入门", 5);   // 新增图书 B001 x5
    CHECK(books.size() == 1u, "新增 B001 后图书数量 = 1");
    CHECK(books[0].getStock() == 5, "B001 初始库存 = 5");

    Admin::addBook(books, "B001", "C++入门", 3);   // 已存在，增加库存
    CHECK(books.size() == 1u, "再次入库 B001 不新增图书");
    CHECK(books[0].getStock() == 8, "B001 库存 = 8（5+3）");

    Admin::addBook(books, "B002", "算法导论", 2);  // 新增 B002
    CHECK(books.size() == 2u, "新增 B002 后图书数量 = 2");
    CHECK(books[1].getStock() == 2, "B002 库存 = 2");

    bool okIn = Admin::removeBook(books, "B001", 3); // 出库 3
    CHECK(okIn == true, "B001 出库 3 本成功");
    CHECK(books[0].getStock() == 5, "B001 出库后库存 = 5");

    bool okFail = Admin::removeBook(books, "B002", 99); // 出库 99（库存不足）
    CHECK(okFail == false, "B002 出库 99 本（库存不足）应失败");

    bool okNotFound = Admin::removeBook(books, "B999", 1); // 不存在的图书
    CHECK(okNotFound == false, "出库不存在的 B999 应失败");

    bool okNeg = Admin::removeBook(books, "B001", -5); // 负数出库
    CHECK(okNeg == false, "负数出库应失败");
}

// ---------- 用例四：综合场景（管理员入库 -> 用户借阅 -> 归还） ----------
void testIntegration() {
    cout << "\n===== 用例四：综合场景 =====" << endl;

    vector<Book> books;
    Admin::addBook(books, "B100", "设计模式", 2);   // 入库 2 本

    User u("李四", "abc");

    // 用户借阅 1 本 -> 库存减一，借阅记录 +1
    bool borrowOK = books[0].borrowOne() && u.borrowBook("B100");
    CHECK(borrowOK == true, "用户借阅 B100 成功");
    CHECK(books[0].getStock() == 1, "借阅后馆藏库存 = 1");
    CHECK(u.borrowedCount() == 1u, "用户借阅数 = 1");

    // 归还 -> 库存加一，借阅记录 -1
    bool returnOK = u.returnBook("B100") && (books[0].returnOne(), true);
    CHECK(returnOK == true, "用户归还 B100 成功");
    CHECK(books[0].getStock() == 2, "归还后馆藏库存 = 2");
    CHECK(u.borrowedCount() == 0u, "归还后用户借阅数 = 0");
}

int main() {
    cout << "======== 图书管理系统 - 功能测试开始 ========" << endl;

    testBook();
    testUser();
    testAdmin();
    testIntegration();

    cout << "\n======== 测试结果 ========" << endl;
    cout << "通过: " << passCount << "  失败: " << failCount << endl;
    if (failCount == 0) {
        cout << ">>> 全部测试用例通过，基本功能正常 <<<" << endl;
        return 0;
    } else {
        cout << ">>> 存在失败用例，请检查 <<<" << endl;
        return 1;
    }
}
